// Everything an operator has to change is on this screen and nowhere else.
//
// The API key is deliberately absent. It is read from the CALL_E_API_KEY environment
// variable at execution time so it never lands in workflow data, an export, or a git
// history. See the plugin README for where to put it in your n8n deployment.
return [{
  json: {
    schoolName: "Redhill Primary",
    // Placeholder numbers. The next node refuses to run until these are replaced.
    // +91 555 is not assignable to an Indian subscriber, so nothing here can ring.
    students: [
      { id: "S-1041", name: "Aarav",  phones: ["+915550000001"], locale: "en-IN", consent: true },
      { id: "S-1042", name: "Diya",   phones: ["+915550000002"], locale: "hi-IN", consent: true },
      { id: "S-1043", name: "Kavya",  phones: ["+915550000003", "+915550000009"], locale: "ta-IN", consent: true },
      { id: "S-1044", name: "Rohan",  phones: ["+915550000004"], locale: "ta-IN", consent: true },
      { id: "S-1045", name: "Meera",  phones: ["+915550000005"], locale: "en-IN", consent: false },
      { id: "S-1046", name: "Ishaan", phones: ["+915550000006", "+915550000007"], locale: "ta-IN", consent: true },
    ],
    absenceDate: new Date().toISOString().slice(0, 10),
    apiBaseUrl: "https://api.heycall-e.com",
    // A wave, not a broadcast. CALL-E's own guidance is against starting every call at
    // once, and there is no cancel endpoint, so this cap is the only brake that exists.
    concurrency: 3,
    maxWaitSeconds: 240,
    dryRun: true,
  },
}];

// Fail before dialling, not halfway through a wave.
const cfg = $input.first().json;
const problems = [];

if (!process.env.CALL_E_API_KEY && !cfg.dryRun) {
  problems.push("CALL_E_API_KEY is not set. Set it in your n8n deployment, or leave dryRun true.");
}

const PLACEHOLDER = /^\+91555/;
const e164 = /^\+[1-9]\d{7,14}$/;

for (const student of cfg.students || []) {
  for (const phone of student.phones || []) {
    if (!e164.test(phone)) {
      problems.push(`${student.id}: ${phone} is not an E.164 number`);
    }
    if (PLACEHOLDER.test(phone) && !cfg.dryRun) {
      problems.push(`${student.id}: ${phone} is a shipped placeholder. Replace it with a number you are authorised to call.`);
    }
  }
  if (!Array.isArray(student.phones) || student.phones.length === 0) {
    problems.push(`${student.id}: no phone numbers`);
  }
}

if (problems.length > 0) {
  throw new Error("Refusing to run:\n  " + problems.join("\n  "));
}

return [{ json: cfg }];

// One item per student, so the loop below is a wave and not a single request.
const cfg = $input.first().json;
return (cfg.students || []).map((student) => ({
  json: { ...student, schoolName: cfg.schoolName, absenceDate: cfg.absenceDate,
          apiBaseUrl: cfg.apiBaseUrl, maxWaitSeconds: cfg.maxWaitSeconds,
          dryRun: cfg.dryRun },
}));

// Consent is never inferred. A row without recorded consent is refused, not defaulted,
// and it is reported as skipped rather than folded into the failures, because no call was
// placed and reporting one would be a lie about what this workflow did.
const out = [];
for (const item of $input.all()) {
  if (item.json.consent === true) {
    out.push(item);
  } else {
    out.push({ json: { ...item.json, resolution: "skipped", attempts: 0,
                       reason: "no recorded consent to be called", needsAHuman: false,
                       skip: true } });
  }
}
return out;

// One call request for one student.
const row = $input.first().json;
if (row.skip) {
  return [{ json: row }];
}

// Derived from (student, date), so a retry after a timeout reuses the same key instead of
// minting a fresh one. Without this a network failure double-calls a family.
const idempotencyKey = `absence-${row.id}-${row.absenceDate}`;

return [{
  json: {
    ...row,
    idempotencyKey,
    request: {
      // The whole fallback chain goes in the request. CALL-E tries them in order; the
      // workflow does not orchestrate retries itself.
      phones: row.phones,
      // The language belongs to the family, not to the deployment. This is the single
      // field that makes the recipe work outside one country.
      locale: row.locale,
      task: [
        "This is an automated call from the school attendance office.",
        "You are speaking with an AI assistant, not a person.",
        "You can ask to speak to a member of staff at any time and I will arrange a callback.",
        "",
        `You are calling on behalf of ${row.schoolName} about ${row.name}, who was marked absent on ${row.absenceDate} and whose absence has not yet been explained.`,
        "Ask, politely and briefly: the reason for the absence, and when the student is expected back.",
        "Do not give advice. Do not discuss anything except this absence. If the person is distressed, asks for a human, disputes the absence, or says anything suggesting the student may be at risk, stop asking questions, say a member of staff will call back today, and end the call politely.",
      ].join("\n"),
      result_schema: {
        type: "object",
        required: ["reason_category", "expected_return"],
        properties: {
          reason_category: { type: "string", enum: ["illness", "medical_appointment", "family_emergency", "religious_observance", "transport", "other", "unknown"] },
          expected_return: { type: "string", enum: ["today", "tomorrow", "later_this_week", "longer", "unknown"] },
          parent_confirmed_aware: { type: "string", enum: ["yes", "no", "unknown"] },
          free_text_note: { type: "string" },
        },
      },
    },
  },
}];

// Place the call and wait for it to finish, with a hard ceiling on the wait.
const row = $input.first().json;
if (row.skip) {
  return [{ json: row }];
}

// dryRun returns a shaped response and places no call, so the whole recipe can be run
// once end to end before it is pointed at a real number.
if (row.dryRun) {
  const shapes = {
    // Two rows that close. An explicit "yes" on parent_confirmed_aware is what closing
    // requires, and leaving that field out of these shapes is how the first version of this
    // demo escalated all three and reported a resolution rate of zero.
    "S-1041": { status: "completed", structured_result: { reason_category: "illness", expected_return: "tomorrow", parent_confirmed_aware: "yes" } },
    "S-1042": { status: "completed", structured_result: { reason_category: "medical_appointment", expected_return: "today", parent_confirmed_aware: "yes" } },
    // A schema-valid answer from a parent who did not know. Resolved, escalated, not closed,
    // and first in the queue. This is the row worth reading in the output.
    "S-1043": { status: "completed", structured_result: { reason_category: "transport", expected_return: "today", parent_confirmed_aware: "no" }, attempts: 2 },
    // The two shapes that are easy to get wrong, both taken from real calls.
    "S-1044": { status: "completed", structured_result: null },
    "S-1046": { status: "no_answer", structured_result: null, attempts: 2 },
  };
  const shape = shapes[row.id] || { status: "completed", structured_result: null };
  const attempts = Array.from({ length: shape.attempts || 1 }, (_, i) => ({
    provider_call_id: `dry_${row.id}_${i + 1}`,
  }));
  return [{ json: { ...row, recipient: { ...shape, attempts }, placedByThisRun: false } }];
}

const headers = {
  Authorization: `Bearer ${process.env.CALL_E_API_KEY}`,
  "Idempotency-Key": row.idempotencyKey,
  "Content-Type": "application/json",
};

const created = await this.helpers.httpRequest({
  method: "POST",
  url: `${row.apiBaseUrl}/v1/calls`,
  headers,
  body: row.request,
  json: true,
  timeout: 30000,
});

const callId = created.id || created.call_id;
const deadline = Date.now() + (row.maxWaitSeconds || 240) * 1000;
let call = created;

while (Date.now() < deadline) {
  const terminal = ["completed", "failed", "no_answer", "busy", "cancelled"];
  const recipient = (call.recipients || [])[0];
  if (recipient && terminal.includes(recipient.status)) {
    break;
  }
  await new Promise((resolve) => setTimeout(resolve, 5000));
  call = await this.helpers.httpRequest({
    method: "GET",
    url: `${row.apiBaseUrl}/v1/calls/${callId}`,
    headers: { Authorization: headers.Authorization },
    json: true,
    timeout: 30000,
  });
}

return [{ json: { ...row, callId, recipient: (call.recipients || [])[0] || null,
                  placedByThisRun: true } }];

/**
 * Decide what one CALL-E call actually achieved. Three outcomes, not two.
 *
 * This is the only interesting logic in the recipe and it is kept in its own file so it
 * can be tested with `node --test` before it is pasted into a workflow node. The copy
 * inside `absence-wave.workflow.json` is generated from this file, and
 * `classify.test.mjs` fails if the two ever drift apart.
 *
 * The rule it implements, and why each branch exists:
 *
 *   resolved      A result came back and at least one required field says something.
 *   undetermined  A conversation happened and produced nothing usable. Two shapes:
 *                 `structured_result` is null, or every required field is uninformative.
 *   failed        Nobody was reached on any number.
 *
 * A second, independent axis rides alongside those three:
 *
 *   escalation    "safeguarding" when the parent did not confirm they already knew their
 *                 child was absent. It is not a fourth resolution. Making it one would mean
 *                 a call could be counted in two buckets or in neither, and the three
 *                 outcomes above exist to be counted. A safeguarding call is still
 *                 `resolved`: the answer arrived and it was schema-valid. What changes is
 *                 that it is not closed automatically and a person owes it a callback.
 *
 * The middle outcome is the point. A pipeline with two buckets has to file
 * "the call connected but we learned nothing" somewhere, and filing it with the
 * successes is how a dashboard reports full coverage for a child nobody heard about.
 *
 * Both `undetermined` shapes were found by placing real calls, not by reading the API
 * docs. The second one is the subtle one: CALL-E returns a schema-valid result with every
 * required field set to "unknown" when the person says "I cannot talk now". That is a
 * correct response to an honest enum and it is worth nothing.
 */

/** Values that mean the question was asked and not answered. */
const UNINFORMATIVE = new Set(["unknown"]);

/** Required by the absence schema. Only these count towards uninformative. */
const REQUIRED_FIELDS = ["reason_category", "expected_return"];

function isObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

/**
 * Every required field uninformative means nothing was learned.
 *
 * `all`, not `any`. One field answered is still an answer, and treating a single unknown
 * as failure would push resolved cases back onto a person's desk for no reason.
 */
function isUninformative(result) {
  if (!isObject(result) || REQUIRED_FIELDS.length === 0) {
    return false;
  }
  return REQUIRED_FIELDS.every((name) => {
    const value = result[name];
    return typeof value === "string" && UNINFORMATIVE.has(value.trim().toLowerCase());
  });
}

/**
 * Pull the structured result for one recipient.
 *
 * Deliberately never falls back to a task-level `structured_result`. On a fan-out call
 * that fallback files one family's answer against another family's child, which is a
 * data-protection incident rather than a bug. If this recipient has no result of its own,
 * it has no result.
 */
function recipientResult(recipient) {
  if (!isObject(recipient)) {
    return null;
  }
  const result = recipient.structured_result;
  return isObject(result) ? result : null;
}

/**
 * The last attempt is the one that decides the call.
 *
 * A student with two guardian numbers may fail on the first and connect on the second.
 * Reading the first attempt would cite the id of the attempt that did not connect and
 * report a reached family as unreachable.
 */
function lastAttempt(recipient) {
  const attempts = isObject(recipient) && Array.isArray(recipient.attempts)
    ? recipient.attempts
    : [];
  return attempts.length > 0 ? attempts[attempts.length - 1] : null;
}

function attemptCount(recipient) {
  return isObject(recipient) && Array.isArray(recipient.attempts)
    ? recipient.attempts.length
    : 0;
}

/**
 * Minutes a school has to return a safeguarding call before the window is missed.
 *
 * Not a legal figure. It is the number this recipe prints so the queue carries a deadline
 * instead of an adjective, and a school with a different policy should change it here.
 */
const SAFEGUARDING_CALLBACK_MINUTES = 30;

/**
 * Did the parent confirm they already knew their child was not in school?
 *
 * Fails closed. Anything that is not an explicit "yes", including a missing field, an
 * "unknown", or a value nobody anticipated, escalates. The cost of escalating a call that
 * did not need it is a phone call. The cost of the other mistake is a child nobody looked
 * for, so the two errors are not worth trading against each other.
 */
function safeguardingEscalation(result) {
  const confirmed = isObject(result) ? result.parent_confirmed_aware : undefined;
  return String(confirmed === undefined || confirmed === null ? "" : confirmed)
    .trim()
    .toLowerCase() === "yes"
    ? "none"
    : "safeguarding";
}

/**
 * Classify one recipient of one call.
 *
 * Returns { resolution, reason, attempts, providerCallId, escalation, needsAHuman }.
 */
function classifyRecipient(recipient) {
  const attempts = attemptCount(recipient);
  const last = lastAttempt(recipient);
  const providerCallId = isObject(last) && typeof last.provider_call_id === "string"
    ? last.provider_call_id
    : null;

  const connected = isObject(recipient) && recipient.status === "completed";

  if (!connected) {
    return {
      resolution: "failed",
      reason: `nobody answered after trying ${attempts} number(s)`,
      attempts,
      providerCallId,
      escalation: "none",
      needsAHuman: true,
    };
  }

  const result = recipientResult(recipient);

  if (result === null) {
    return {
      resolution: "undetermined",
      reason: "the call completed but returned no structured result",
      attempts,
      providerCallId,
      escalation: "none",
      needsAHuman: true,
    };
  }

  if (isUninformative(result)) {
    return {
      resolution: "undetermined",
      reason: "every required field came back unknown, so nothing was learned",
      attempts,
      providerCallId,
      escalation: "none",
      needsAHuman: true,
    };
  }

  const escalation = safeguardingEscalation(result);

  return {
    resolution: "resolved",
    reason: escalation === "safeguarding"
      ? "schema-valid answer received, escalated as safeguarding and not closed automatically"
      : "schema-valid answer received",
    attempts,
    providerCallId,
    escalation,
    needsAHuman: escalation !== "none",
  };
}

/**
 * Mask a number for display. Never print a family's phone number into an execution log.
 */
function maskNumber(value) {
  if (typeof value !== "string" || value.length < 4) {
    return "****";
  }
  return `${value.slice(0, 3)}${"*".repeat(Math.max(0, value.length - 6))}${value.slice(-3)}`;
}

/**
 * Roll a wave up into the three counts plus the queue that still needs a person.
 *
 * `skipped` is separate from `failed` on purpose: a row with no recorded consent was never
 * dialled, so counting it as a failure would report a call that never happened.
 */
function summariseWave(rows) {
  const counts = { resolved: 0, undetermined: 0, failed: 0, skipped: 0 };
  const queue = [];
  let attemptsBilled = 0;
  let attemptsResolved = 0;
  let escalated = 0;

  for (const row of Array.isArray(rows) ? rows : []) {
    const resolution = row && row.resolution;
    if (!Object.prototype.hasOwnProperty.call(counts, resolution)) {
      continue;
    }
    counts[resolution] += 1;
    const isEscalated = row.escalation === "safeguarding";
    if (isEscalated) {
      escalated += 1;
    }
    const attempts = Number.isInteger(row.attempts) ? row.attempts : 0;
    attemptsBilled += attempts;
    // An escalated call is resolved and is not closed, so its attempts are still somebody's
    // work. Counting them as saved would report a saving on the calls that cost the most.
    if (resolution === "resolved" && !isEscalated) {
      attemptsResolved += attempts;
    }
    if (row.needsAHuman) {
      queue.push({ id: row.id, reason: row.reason, escalation: row.escalation || "none" });
    }
  }

  // Safeguarding cases sort to the top of the queue. A list where the urgent row is third
  // is a list that gets worked from the top.
  queue.sort((a, b) => (b.escalation === "safeguarding") - (a.escalation === "safeguarding"));

  const attempted = counts.resolved + counts.undetermined + counts.failed;
  // `closed` is the honest numerator. `resolved` counts every schema-valid answer, and an
  // escalated one is not finished with, so a rate computed from `resolved` would rise every
  // time the recipe found something serious.
  const closed = counts.resolved - escalated;
  return {
    counts,
    attempted,
    escalated,
    closed,
    safeguardingCallbackMinutes: SAFEGUARDING_CALLBACK_MINUTES,
    attemptsBilled,
    attemptsResolved,
    attemptsOpen: attemptsBilled - attemptsResolved,
    resolutionRate: attempted === 0 ? null : closed / attempted,
    queue,
  };
}

const RULES = { UNINFORMATIVE, REQUIRED_FIELDS };

// --- node wiring ---------------------------------------------------------------------
const row = $input.first().json;
if (row.skip) {
  return [{ json: row }];
}
const verdict = classifyRecipient(row.recipient);
return [{
  json: {
    id: row.id,
    locale: row.locale,
    phone: maskNumber((row.phones || [])[0]),
    placedByThisRun: row.placedByThisRun === true,
    ...verdict,
  },
}];

